{
  "implementation": "import json

def solve(case):
    # Validate required fields
    required_fields = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for field in required_fields:
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    initial_state = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    # Validate initial state exists in transitions
    if initial_state not in transitions:
        raise ValueError(f"Initial state '{initial_state}' not found in transitions")

    # Validate each transition structure
    for state_name, trans in transitions.items():
        if 'kind' not in trans:
            raise ValueError(f"Transition '{state_name}' missing 'kind'")
        kind = trans['kind']
        if kind == 'action':
            if 'action' not in trans:
                raise ValueError(f"Action transition '{state_name}' missing 'action'")
            if 'next_by_observation' not in trans:
                raise ValueError(f"Action transition '{state_name}' missing 'next_by_observation'")
            # action must be a string
            if not isinstance(trans['action'], str):
                raise ValueError(f"Action in transition '{state_name}' must be a string")
            # validate that all next states exist
            for obs, next_state in trans['next_by_observation'].items():
                if next_state not in transitions:
                    raise ValueError(f"Transition '{state_name}' next_by_observation maps to unknown state '{next_state}'")
            if 'default_next' in trans and trans['default_next'] not in transitions:
                raise ValueError(f"Transition '{state_name}' default_next maps to unknown state '{trans['default_next']}'")
        elif kind == 'final':
            if 'value' not in trans:
                raise ValueError(f"Final transition '{state_name}' missing 'value'")
            # value can be string or null - accept any
        else:
            raise ValueError(f"Transition '{state_name}' has unknown kind '{kind}'")

    # Simulate ReAct loop
    current_state = initial_state
    step = 0
    trace = []
    final_value = None
    status = None

    while step < max_steps:
        trans = transitions[current_state]
        if trans['kind'] == 'final':
            # reached final state
            final_value = trans['value']
            status = 'completed'
            break

        # action transition
        tool = trans['action']
        if tool not in tool_obs:
            raise ValueError(f"Tool '{tool}' not found in tool_observations")
        observation = tool_obs[tool]

        # determine next state
        next_by_obs = trans['next_by_observation']
        if observation in next_by_obs:
            next_state = next_by_obs[observation]
        elif 'default_next' in trans:
            next_state = trans['default_next']
        else:
            raise ValueError(f"No observation '{observation}' in transition '{current_state}' next_by_observation and no default_next")

        if next_state not in transitions:
            raise ValueError(f"Next state '{next_state}' not found in transitions")

        # record trace entry
        step += 1
        trace.append({
            'step': step,
            'state': current_state,
            'action': tool,
            'observation': observation
        })

        # transition to next state
        current_state = next_state

        # check if new state is final (before next loop iteration consumes step)
        if transitions[current_state]['kind'] == 'final':
            final_value = transitions[current_state]['value']
            status = 'completed'
            break

    if status is None:
        # max steps reached without final state
        status = 'max_steps_reached'
        final_value = None
        # Include the current state? The trace already records actions that were taken.
        # Optionally we might want to include a final trace entry? But spec says stop on completion or max steps.
        # No further action is taken, so trace is as is.

    return {
        'status': status,
        'final': final_value,
        'trace': trace
    }
